24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
27	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
28	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
