32	    @Mapping(target = "membershipLevel", expression = "java(resolveMembershipLevel(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(resolveContactPreference(owner))")
34	    @Mapping(target = "ageBand", expression = "java(resolveAgeBand(owner))")
35	    @Mapping(target = "identityKey", expression = "java(owner.getIdentityKey())")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    Owner toOwner(OwnerDto ownerDto);
39	
40	    /**
41	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
42	     */
43	    default String formatDisplayName(Owner owner) {
44	        return owner.getLastName() + ", " + owner.getFirstName();
45	    }
46	
47	    /**
48	     * Formats the owner's stored E.164 telephone for human display (country code, a space and the
49	     * national digits grouped in threes), leaving the raw {@code telephone} in E.164 form.
50	     */
51	    default String formatTelephoneDisplay(Owner owner) {
52	        return TelephoneFormatter.toDisplay(owner.getTelephone());
53	    }
54	
55	    /**
56	     * Formats the owner's initials as the upper-cased first letters of firstName and
57	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
58	     */
59	    default String formatInitials(Owner owner) {
60	        return initial(owner.getFirstName()) + initial(owner.getLastName());
61	    }
62	
63	    /** The upper-cased first letter of {@code name} followed by a dot. */
64	    private String initial(String name) {
65	        return Character.toUpperCase(name.charAt(0)) + ".";
66	    }
67	
68	    /**
69	     * Derives the owner's locality (canonical region) from the leading {@code <REGION>} segment of
70	     * its {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality always agrees with the
71	     * region encoded in the owner's identity.
72	     */
73	    default String resolveLocality(Owner owner) {
74	        String customerCode = owner.getCustomerCode();
75	        return customerCode.substring(0, customerCode.indexOf('-'));
76	    }
77	
78	    /**
79	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
80	     * last two digits of the registration date year, e.g. {@code "LON-SMI-0007-M26"}.
81	     */
82	    default String formatMembershipNumber(Owner owner) {
83	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
84	    }
85	
86	    /**
87	     * Computes the Luhn check digit over the decimal digits of the owner's customer code.
88	     */
89	    default Integer computeCheckDigit(Owner owner) {
90	        return Luhn.checkDigit(owner.getCustomerCode());
91	    }
92	
93	    /** The minimum tenure, in days, an owner must exceed to qualify for membership level 4. */
94	    int TENURE_LEVEL_THRESHOLD_DAYS = 365;
95	
96	    /**
97	     * Resolves the owner's numeric membership level: starts at {@code 1}, plus {@code 1} when an
98	     * email is present, plus {@code 1} when the owner has no namesakes (namesakeCount is 0), plus
99	     * {@code 1} when the owner's tenure exceeds {@value #TENURE_LEVEL_THRESHOLD_DAYS} days. Since
100	     * the pre-tenure factors cap at level {@code 3}, level {@code 4} requires tenure of more than
101	     * {@value #TENURE_LEVEL_THRESHOLD_DAYS} days, which a newly created (zero-tenure) owner never
102	     * has.
103	     */
104	    default Integer resolveMembershipLevel(Owner owner) {
105	        int level = 1;
106	        if (hasEmail(owner)) {
107	            level++;
108	        }
109	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
110	            level++;
111	        }
112	        if (owner.getTenureDays() > TENURE_LEVEL_THRESHOLD_DAYS) {
113	            level++;
114	        }
115	        return level;
116	    }
117	
118	    /**
119	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
120	     * present, otherwise {@code "PHONE"}.
121	     */
122	    default String resolveContactPreference(Owner owner) {
123	        return hasEmail(owner) ? "EMAIL" : "PHONE";
124	    }
125	
126	    /** Whether the owner has a non-blank email address. */
127	    private boolean hasEmail(Owner owner) {
128	        return owner.getEmail() != null && !owner.getEmail().isBlank();
129	    }
130	
131	    /**
132	     * Resolves the owner's age band (as a string) from its birth date against its registration
133	     * date, or {@code null} when the owner has no birth date.
134	     */
135	    default String resolveAgeBand(Owner owner) {
136	        return owner.getAgeBand() == null ? null : owner.getAgeBand().name();
137	    }
138	
139	    @Mapping(target = "id", ignore = true)
140	    @Mapping(target = "pets", ignore = true)
141	    @Mapping(target = "householdId", ignore = true)
142	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
143	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
144	    Owner toOwner(OwnerFieldsDto ownerDto);
145	
146	    /**
147	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
148	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
149	     */
150	    @Named("normalizeAddress")
151	    default String normalizeAddress(String address) {
152	        return AddressNormalizer.normalize(address);
153	    }
154	
155	    /**
156	     * Store the telephone in E.164 form. Validation ({@code @Telephone}) has already guaranteed
157	     * the raw value normalizes to a valid E.164 number.
158	     */
159	    @Named("normalizeTelephone")
160	    default String normalizeTelephone(String telephone) {
161	        return TelephoneNormalizer.toE164(telephone);
162	    }
163	
164	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
165	
166	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
167	
168	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
169	        OwnerPageDto ownerPageDto = new OwnerPageDto();
170	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
171	        ownerPageDto.setPage(ownerPage.getNumber());
172	        ownerPageDto.setSize(ownerPage.getSize());
173	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
174	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
175	        return ownerPageDto;
176	    }
177	}
